# ──────────────────────────────────────────────────────────────────────────────

def main() -> None:
    db = SessionLocal()
    try:
        existing = {r[0] for r in db.query(Exercise.name).all()}
        seen: set[str] = set()
        new_exercises = []
        for name, mg, sec, eq, lvl, inst, contra in EXTRA_EXERCISES:
            if name in existing or name in seen:
                continue
            seen.add(name)
            new_exercises.append(Exercise(
                name=name,
                muscle_group=mg,
                secondary_muscles=sec,
                equipment=eq,
                level=lvl,
                instructions=inst,
                contraindications=contra,
            ))

        db.add_all(new_exercises)
        db.commit()

        print(f"✓ Adicionados {len(new_exercises)} exercícios.")
        print(f"  (ignorados {len(EXTRA_EXERCISES) - len(new_exercises)} já existentes)")

        # Summary
        from sqlalchemy import text, func
        rows = (
            db.query(Exercise.muscle_group, func.count(Exercise.id))
            .group_by(Exercise.muscle_group)
            .order_by(func.count(Exercise.id).desc())
            .all()
        )
        total = sum(n for _, n in rows)
        print(f"\nTotal no banco: {total}")
        for mg, count in rows:
            print(f"  {mg}: {count}")
    finally:
        db.close()


if __name__ == "__main__":
    main()
